mapper.select:
SELECT a.id, a.type_id, t.type_name, a.apply_reason, a.family_situation, a.family_income, a.family_members, a.per_capita_income, a.special_type, a.special_proof, a.status, a.reviewer_id, ru.name AS reviewer_name, a.review_comment, a.review_time, a.student_id, s.student_no, s.name AS student_name, s.college, s.class_name, a.create_time, a.update_time FROM grant_application a LEFT JOIN grant_type t ON a.type_id = t.id LEFT JOIN sys_user ru ON a.reviewer_id = ru.user_id AND ru.role = 1 LEFT JOIN student s ON a.student_id = s.id
AND a.student_id = #{studentId}
AND a.status = #{status}
AND a.type_id = #{typeId}
AND (s.student_no LIKE CONCAT('%', #{keyword}, '%') OR s.name LIKE CONCAT('%', #{keyword}, '%'))
AND (a.special_type = 0 OR a.special_type IS NULL)
AND a.special_type > 0
AND s.counselor_id = #{counselorId}
ORDER BY a.create_time DESC

SELECT a.id, a.type_id, t.type_name, a.apply_reason, a.family_situation, a.family_income, a.family_members, a.per_capita_income, a.special_type, a.special_proof, a.status, a.reviewer_id, ru.name AS reviewer_name, a.review_comment, a.review_time, a.student_id, s.student_no, s.name AS student_name, s.college, s.class_name, a.create_time, a.update_time FROM grant_application a LEFT JOIN grant_type t ON a.type_id = t.id LEFT JOIN sys_user ru ON a.reviewer_id = ru.user_id AND ru.role = 1 LEFT JOIN student s ON a.student_id = s.id LEFT JOIN score_record sr ON a.id = sr.application_id WHERE a.status = 1 AND a.special_type = 0 AND sr.id IS NULL
AND (s.student_no LIKE CONCAT('%', #{keyword}, '%') OR s.name LIKE CONCAT('%', #{keyword}, '%'))
AND a.type_id = #{typeId}
AND s.counselor_id = #{counselorId}
ORDER BY a.create_time DESC
